#include "AutoFit.h"
#include <chrono>
#include <iostream>
int main(){nova::SpectralModel m;m.count=48;m.root=60;m.duration=3;m.tracked=true;for(int f=0;f<nova::modelFrames;++f)m.times[f]=3*f/static_cast<float>(nova::modelFrames-1);for(int j=0;j<48;++j){m.partials[j].frequency=200+j*173;for(int f=0;f<nova::modelFrames;++f){m.partials[j].amplitude[f]=.01f;m.partials[j].frequencyRatio[f]=1+.01f*std::sin(f*.7f);}}for(auto& b:m.noise)b.fill(.003f);nova::Params p;p.engine=1;p.cutoff=20000;p.envAmount=p.resonance=0;p.delay=p.reverb=0;p.sustain=1;nova::Engine e;e.configure(p);e.prepare(48000);e.setModel(&m);for(int i=0;i<16;++i)e.noteOn(1,48+i,1);std::vector<float> l(48000),r(l.size());auto a=std::chrono::steady_clock::now();e.render(l.data(),r.data(),48000);double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-a).count();for(float v:l)if(!std::isfinite(v))return 1;std::cout<<"16 voices / 48 tracked partials / 12 noise bands / 48kHz / 1s audio: "<<seconds<<"s CPU wall time (native host only)\n";return 0;}
